def energy_j(bytes_moved, pj_per_byte, ops, pj_per_op):
    return (bytes_moved * pj_per_byte + ops * pj_per_op) * 1e-12


def movement_share(bytes_moved, pj_per_byte, ops, pj_per_op):
    move = bytes_moved * pj_per_byte
    return move / (move + ops * pj_per_op)


print(energy_j(1e12, 100, 1e13, 1), 'J,', round(100 * movement_share(1e12, 100, 1e13, 1)), '% moving data')
